package com.etic.licensecontrol.audit;
import com.etic.licensecontrol.common.CrudService;import java.util.*;import org.springframework.web.bind.annotation.*;
// LEGACY TEMPORAL: license_validation_events conserva Id_Application; su filtro histórico usa system_application_links.
@RestController @RequestMapping("/api/admin") public class OverviewController {private final CrudService c;OverviewController(CrudService c){this.c=c;}@GetMapping("/dashboard")Map<String,Object>dashboard(){var d=c.db();Map<String,Object>m=new LinkedHashMap<>();m.put("activeUsers",d.queryForObject("SELECT COUNT(*) FROM users WHERE Is_Active=TRUE",Map.of(),Long.class));m.put("activeSystems",d.queryForObject("SELECT COUNT(*) FROM systems WHERE Is_Active=TRUE",Map.of(),Long.class));m.put("applications",d.queryForObject("SELECT COUNT(*) FROM systems s JOIN system_licensing sl ON sl.Id_System=s.Id_System WHERE s.Is_Active=TRUE AND sl.Is_Active=TRUE",Map.of(),Long.class));m.put("activeLicenses",d.queryForObject("SELECT COUNT(*) FROM licenses l JOIN systems s ON s.Id_System=l.Id_System JOIN system_licensing sl ON sl.Id_System=s.Id_System WHERE l.Is_Active=TRUE AND l.Status='ACTIVE' AND l.Valid_Until>=CURRENT_DATE AND s.Is_Active=TRUE AND sl.Is_Active=TRUE",Map.of(),Long.class));m.put("devices",d.queryForObject("SELECT COUNT(*) FROM licensed_devices WHERE Is_Active=TRUE AND Status='ACTIVE'",Map.of(),Long.class));m.put("employees",d.queryForObject("SELECT COUNT(*) FROM users u JOIN user_types t ON t.Id_User_Type=u.Id_User_Type WHERE u.Is_Active=TRUE AND t.Is_Active=TRUE AND t.Code='EMPLOYEE'",Map.of(),Long.class));m.put("externalUsers",d.queryForObject("SELECT COUNT(*) FROM users u JOIN user_types t ON t.Id_User_Type=u.Id_User_Type WHERE u.Is_Active=TRUE AND t.Is_Active=TRUE AND t.Code='EXTERNAL'",Map.of(),Long.class));m.put("expiringLicenses",d.queryForList("SELECT l.* FROM licenses l JOIN systems s ON s.Id_System=l.Id_System JOIN system_licensing sl ON sl.Id_System=s.Id_System WHERE l.Is_Active=TRUE AND l.Status='ACTIVE' AND l.Valid_Until BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY) AND s.Is_Active=TRUE AND sl.Is_Active=TRUE ORDER BY l.Valid_Until LIMIT 10",Map.of()));m.put("latestAccess",d.queryForList("SELECT Username_Attempted,Success,Occurred_At FROM authentication_events ORDER BY Occurred_At DESC LIMIT 10",Map.of()));m.put("latestEvents",d.queryForList("SELECT Action,Entity_Type,Created_At FROM audit_events ORDER BY Created_At DESC LIMIT 10",Map.of()));return m;}@GetMapping("/audit")Map<String,Object>audit(@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(required=false)String user,@RequestParam(required=false)String system,@RequestParam(required=false)String eventType,@RequestParam(required=false)String result,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,@RequestParam(defaultValue="desc")String direction,@RequestParam(defaultValue="")String search){Map<String,Object>p=new HashMap<>();p.put("size",Math.min(Math.max(size,1),100));p.put("offset",Math.max(page,0)*Math.min(Math.max(size,1),100));p.put("search","%"+search+"%");p.put("from",blank(from));p.put("to",blank(to));p.put("user",blank(user));p.put("system",blank(system));p.put("event",blank(eventType));p.put("result",blank(result));p.put("success",result==null||result.isBlank()?null:"SUCCESS".equals(result)?1:0);return Map.of("authentication",c.db().queryForList("SELECT * FROM authentication_events WHERE (:from IS NULL OR Occurred_At>=:from) AND (:to IS NULL OR Occurred_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_User=:user) AND (:system IS NULL OR Id_System=:system) AND (:event IS NULL OR Event_Type=:event) AND (:success IS NULL OR Success=:success) AND (Username_Attempted LIKE :search OR Event_Type LIKE :search) ORDER BY Occurred_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p),"audit",c.db().queryForList("SELECT * FROM audit_events WHERE (:from IS NULL OR Created_At>=:from) AND (:to IS NULL OR Created_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_User=:user) AND (:system IS NULL OR Id_System=:system) AND (:event IS NULL OR Action=:event) AND (Action LIKE :search OR Entity_Type LIKE :search) ORDER BY Created_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p),"licenseValidation",c.db().queryForList("SELECT * FROM license_validation_events WHERE (:from IS NULL OR Created_At>=:from) AND (:to IS NULL OR Created_At<DATE_ADD(:to,INTERVAL 1 DAY)) AND (:user IS NULL OR Id_Usuario=:user) AND (:event IS NULL OR Event_Type=:event) AND (:result IS NULL OR Result=:result) AND (:system IS NULL OR Id_Application IN (SELECT Id_Application FROM system_application_links WHERE Id_System=:system)) AND (CAST(Event_Type AS CHAR) LIKE :search) ORDER BY Created_At "+("asc".equals(direction)?"ASC":"DESC")+" LIMIT :size OFFSET :offset",p));}private Object blank(String s){return s==null||s.isBlank()?null:s;}}
